import 'package:cloud_firestore/cloud_firestore.dart';`nimport 'dart:typed_data';`nimport 'package:flutter/material.dart';`nimport 'package:pdf/widgets.dart' as pw;`nimport 'package:printing/printing.dart';`nimport '../../core/app_formatters.dart';`nimport '../../core/app_store.dart';`nimport '../../core/subscription_middleware.dart';`nimport '../shared/gradient_card.dart';`nclass SalesScreen extends StatefulWidget {`n  const SalesScreen({`nsuper.key, required this.onFiadoSaleCreated}`n);`n  final VoidCallback onFiadoSaleCreated;`n  @override  State<SalesScreen> createState() => _SalesScreenState();`n}`nclass _SalesScreenState extends State<SalesScreen> {`n  final _subscriptionMiddleware = SubscriptionMiddleware();`n  final _descriptionController = TextEditingController();`n  final _valueController = TextEditingController();`n  final _quantityController = TextEditingController(text: '1');`n  final _customerSearchController = TextEditingController();`n  final _productSearchController = TextEditingController();`n  final _loanDueDateController = TextEditingController();`n  final _loanInterestController = TextEditingController(text: '2');`n  String _mode = 'livre';`n  String _paymentMethod = 'pix';`n  LoanInterestUnit _loanInterestUnit = LoanInterestUnit.month;`n  String? _selectedProductId;`n  CustomerRecord? _selectedCustomer;`n  String _errorText(Object error) {`n    if (error is FirebaseException) {`n      return error.message ?? 'Falha ao salvar no Firebase.';`n    }`n    return error.toString();`n  }`n  String _paymentMethodLabel(String method) {`n    switch (method) {`n      case 'pix':        return 'Pix';`n      case 'dinheiro':        return 'Dinheiro';`n      case 'cartao':        return 'Cartao';`n      case 'fiado':        return 'Fiado';`n      case 'emprestimo':        return 'Emprestimo';`n      default:        return 'Outros';`n    }`n  }`n  Future<Uint8List> _buildReceiptPdfBytes(    _SaleReceiptData data,    ShopProfile profile,  ) async {`n    final doc = pw.Document();`n    final storeName = profile.storeName.trim().isEmpty        ? 'LOJA'        : profile.storeName.trim().toUpperCase();`n    final storeAddress = profile.address.trim();`n    final storePhone = profile.phone.trim();`n    final customerLabel = (data.customerName ?? '').trim().isEmpty        ? 'Nao informado'        : data.customerName!.trim();`n    doc.addPage(      pw.Page(        margin: const pw.EdgeInsets.all(24),        build: (context) {`n          return pw.Container(            padding: const pw.EdgeInsets.all(18),            decoration: pw.BoxDecoration(              border: pw.Border.all(width: 1.2),              borderRadius: pw.BorderRadius.circular(8),            ),            child: pw.Column(              crossAxisAlignment: pw.CrossAxisAlignment.start,              children: [                pw.Center(                  child: pw.Text(                    storeName,                    style: pw.TextStyle(                      fontSize: 16,                      fontWeight: pw.FontWeight.bold,                    ),                  ),                ),                pw.SizedBox(height: 10),                if (storeAddress.isNotEmpty)                  pw.Text(                    storeAddress,                    style: const pw.TextStyle(fontSize: 10.5),                  ),                if (storePhone.isNotEmpty)                  pw.Text(                    'Tel: $storePhone',                    style: const pw.TextStyle(fontSize: 10.5),                  ),                if (storeAddress.isNotEmpty || storePhone.isNotEmpty)                  pw.SizedBox(height: 8),                pw.Text(                  'RECIBO DE VENDA',                  style: pw.TextStyle(                    fontSize: 13,                    fontWeight: pw.FontWeight.bold,                  ),                ),                pw.SizedBox(height: 8),                pw.Text(                  'Data: ${`nAppFormatters.date(data.createdAt)}`n ${`nAppFormatters.time(data.createdAt)}`n',                  style: const pw.TextStyle(fontSize: 10.5),                ),                pw.SizedBox(height: 8),                pw.Text(                  'Descricao: ${`ndata.description}`n',                  style: const pw.TextStyle(fontSize: 10.5),                ),                if (data.productName != null && data.productName!.isNotEmpty)                  pw.Text(                    'Produto: ${`ndata.productName}`n',                    style: const pw.TextStyle(fontSize: 10.5),                  ),                if (data.quantity != null)                  pw.Text(                    'Quantidade: ${`ndata.quantity!.toStringAsFixed(2)}`n',                    style: const pw.TextStyle(fontSize: 10.5),                  ),                pw.Text(                  'Cliente: $customerLabel',                  style: const pw.TextStyle(fontSize: 10.5),                ),                pw.Text(                  'Pagamento: ${`n_paymentMethodLabel(data.paymentMethod)}`n',                  style: const pw.TextStyle(fontSize: 10.5),                ),                pw.Text(                  'Total: ${`nAppFormatters.currency(data.total)}`n',                  style: pw.TextStyle(                    fontSize: 12,                    fontWeight: pw.FontWeight.bold,                  ),                ),                pw.SizedBox(height: 22),                pw.Text('Assinatura do cliente:'),                pw.SizedBox(height: 24),                pw.Container(height: 1, width: 250),                pw.SizedBox(height: 14),                pw.Text(                  'Obrigado pela preferencia.',                  style: const pw.TextStyle(fontSize: 10.5),                ),              ],            ),          );`n        }`n,      ),    );`n    return doc.save();`n  }`n  String _receiptFileName(ShopProfile profile, DateTime createdAt) {`n    final title = profile.storeName.trim().isEmpty        ? 'recibo'        : profile.storeName.trim().replaceAll(' ', '_');`n    final date = AppFormatters.date(createdAt).replaceAll('/', '-');`n    return '${`ntitle}`n_$date.pdf';`n  }`n  Future<void> _shareReceipt(_SaleReceiptData data, ShopProfile profile) async {`n    final bytes = await _buildReceiptPdfBytes(data, profile);`n    final filename = _receiptFileName(profile, data.createdAt);`n    try {`n      await Printing.sharePdf(bytes: bytes, filename: filename);`n    }`n catch (_) {`n      if (!mounted) return;`n      ScaffoldMessenger.of(context).showSnackBar(        const SnackBar(          content: Text('Nao foi possivel compartilhar o comprovante.'),        ),      );`n    }`n  }`n  Future<void> _printReceipt(_SaleReceiptData data, ShopProfile profile) async {`n    final bytes = await _buildReceiptPdfBytes(data, profile);`n    if (!mounted) return;`n    final title = profile.storeName.trim().isEmpty        ? 'Recibo'        : profile.storeName.trim();`n    final fileName = _receiptFileName(profile, data.createdAt);`n    var canPrint = true;`n    var canShare = true;`n    try {`n      final info = await Printing.info();`n      canPrint = info.canPrint;`n      canShare = info.canShare;`n    }`n catch (_) {`n      // Mantem fallback padrao quando o plugin nao informa capacidades.    }`n    if (!canPrint) {`n      if (canShare) {`n        try {`n          await Printing.sharePdf(bytes: bytes, filename: fileName);`n          if (!mounted) return;`n          ScaffoldMessenger.of(context).showSnackBar(            const SnackBar(              content: Text(                'Este dispositivo nao suporta impressao direta. Comprovante pronto para compartilhar.',              ),            ),          );`n          return;`n        }`n catch (_) {`n          // Segue para mensagem final abaixo.        }`n      }`n      if (!mounted) return;`n      ScaffoldMessenger.of(context).showSnackBar(        const SnackBar(          content: Text('Nao foi possivel abrir a impressao neste dispositivo.'),        ),      );`n      return;`n    }`n    try {`n      final opened = await Printing.layoutPdf(        name: '$title - Recibo',        onLayout: (_) async => bytes,      );`n      if (opened) return;`n      if (canShare) {`n        await Printing.sharePdf(bytes: bytes, filename: fileName);`n        if (!mounted) return;`n        ScaffoldMessenger.of(context).showSnackBar(          const SnackBar(            content: Text(              'Nenhuma impressora disponivel. Use compartilhar para enviar o comprovante.',            ),          ),        );`n        return;`n      }`n    }`n catch (_) {`n      if (canShare) {`n        try {`n          await Printing.sharePdf(bytes: bytes, filename: fileName);`n          if (!mounted) return;`n          ScaffoldMessenger.of(context).showSnackBar(            const SnackBar(              content: Text(                'Nao foi possivel abrir a impressao. Comprovante pronto para compartilhar.',              ),            ),          );`n          return;`n        }`n catch (_) {`n          // Segue para mensagem final abaixo.        }`n      }`n      if (!mounted) return;`n      ScaffoldMessenger.of(context).showSnackBar(        const SnackBar(          content: Text('Nao foi possivel abrir a impressao neste dispositivo.'),        ),      );`n    }`n  }`n  Future<String?> _askReceiptAction() async {`n    return showModalBottomSheet<String>(      context: context,      showDragHandle: true,      builder: (context) {`n        return SafeArea(          child: Column(            mainAxisSize: MainAxisSize.min,            children: [              const ListTile(                title: Text(                  'Deseja enviar ou imprimir o comprovante?',                  style: TextStyle(fontWeight: FontWeight.bold),                ),              ),              ListTile(                leading: const Icon(Icons.share),                title: const Text('Enviar via WhatsApp / compartilhar'),                subtitle: const Text('Usa o compartilhamento do aparelho'),                onTap: () => Navigator.of(context).pop('share'),              ),              ListTile(                leading: const Icon(Icons.print_outlined),                title: const Text('Imprimir'),                onTap: () => Navigator.of(context).pop('print'),              ),              ListTile(                leading: const Icon(Icons.check_circle_outline),                title: const Text('Finalizar sem comprovante'),                onTap: () => Navigator.of(context).pop('none'),              ),              const SizedBox(height: 12),            ],          ),        );`n      }`n,    );`n  }`n  Future<void> _cancelCompletedSale(AppStore store, SaleRecord sale) async {`n    final canAccess = await _subscriptionMiddleware.checkAccess(      context,      'removeSale',    );`n    if (!canAccess) return;`n    final confirmed = await showDialog<bool>(      context: context,      builder: (_) => AlertDialog(        title: const Text('Cancelar venda concluida'),        content: Text(          'Deseja cancelar esta venda?\n\nIsso vai remover a venda e desfazer estoque/financeiro quando aplicavel.',        ),        actions: [          TextButton(            onPressed: () => Navigator.of(context).pop(false),            child: const Text('Voltar'),          ),          FilledButton(            onPressed: () => Navigator.of(context).pop(true),            child: const Text('Cancelar venda'),          ),        ],      ),    );`n    if (confirmed != true) return;`n    final error = await store.cancelSale(sale: sale);`n    if (!mounted) return;`n    ScaffoldMessenger.of(context).showSnackBar(      SnackBar(content: Text(error ?? 'Venda cancelada com sucesso.')),    );`n  }`n  @override  void dispose() {`n    _descriptionController.dispose();`n    _valueController.dispose();`n    _quantityController.dispose();`n    _customerSearchController.dispose();`n    _productSearchController.dispose();`n    _loanDueDateController.dispose();`n    _loanInterestController.dispose();`n    super.dispose();`n  }`n  List<CustomerRecord> _customerMatches(List<CustomerRecord> customers) {`n    final query = _customerSearchController.text.trim().toLowerCase();`n    if (query.length < 3) return const <CustomerRecord>[];`n    return customers.where((customer) {`n      if (!customer.isActive) return false;`n      final name = customer.name.toLowerCase();`n      final phone = customer.phone.toLowerCase();`n      return name.startsWith(query) ||          name.contains(query) ||          phone.contains(query);`n    }`n).toList();`n  }`n  void _onCustomerTextChanged(String value) {`n    setState(() {`n      if (_selectedCustomer == null) return;`n      final current = value.trim().toLowerCase();`n      if (current != _selectedCustomer!.name.toLowerCase()) {`n        _selectedCustomer = null;`n      }`n    }`n);`n  }`n  String _normalizeForSearch(String value) {`n    var output = value.toLowerCase().trim();`n    const accentMap = {`n      'a': ['a', '�', '�', '�', '�', '�'],      'e': ['e', '�', '�', '�', '�'],      'i': ['i', '�', '�', '�', '�'],      'o': ['o', '�', '�', '�', '�', '�'],      'u': ['u', '�', '�', '�', '�'],      'c': ['c', '�'],      'n': ['n', '�'],    }`n;`n    for (final entry in accentMap.entries) {`n      for (final variant in entry.value) {`n        if (variant == entry.key) continue;`n        output = output.replaceAll(variant, entry.key);`n      }`n    }`n    output = output.replaceAll(RegExp(r'[^a-z0-9]+'), ' ');`n    output = output.replaceAll(RegExp(r'\s+'), ' ').trim();`n    return output;`n  }`n  List<String> _queryTokens(String query) {`n    final normalized = _normalizeForSearch(query);`n    if (normalized.isEmpty) return const <String>[];`n    return normalized.split(' ').where((token) => token.isNotEmpty).toList();`n  }`n  ProductRecord? _findProductById(    List<ProductRecord> products,    String? productId,  ) {`n    if (productId == null) return null;`n    for (final product in products) {`n      if (product.id == productId) {`n        return product;`n      }`n    }`n    return null;`n  }`n  void _onProductTextChanged(String value, List<ProductRecord> products) {`n    setState(() {`n      final selected = _findProductById(products, _selectedProductId);`n      if (selected == null) {`n        _selectedProductId = null;`n        return;`n      }`n      if (_normalizeForSearch(value) != _normalizeForSearch(selected.name)) {`n        _selectedProductId = null;`n      }`n    }`n);`n  }`n  void _onProductSelectionChanged(    String? value,    List<ProductRecord> products,  ) {`n    setState(() {`n      _selectedProductId = value;`n      final selected = _findProductById(products, value);`n      if (selected == null) {`n        _productSearchController.clear();`n        return;`n      }`n      _productSearchController.text = selected.name;`n    }`n);`n  }`n  List<ProductRecord> _dropdownProducts({`n    required List<ProductRecord> filtered,    required List<ProductRecord> all,    required String? selectedId,  }`n) {`n    final selected = _findProductById(all, selectedId);`n    if (selected == null) return filtered;`n    if (filtered.any((product) => product.id == selected.id)) return filtered;`n    return <ProductRecord>[selected, ...filtered];`n  }`n  List<ProductRecord> _productMatches(List<ProductRecord> products) {`n    final tokens = _queryTokens(_productSearchController.text);`n    if (tokens.isEmpty) return products;`n    final starts = <ProductRecord>[];`n    final contains = <ProductRecord>[];`n    final category = <ProductRecord>[];`n    for (final product in products) {`n      final normalizedName = _normalizeForSearch(product.name);`n      final normalizedCategory = _normalizeForSearch(product.category);`n      final matchesName = tokens.every(normalizedName.contains);`n      final matchesCategory = tokens.every(normalizedCategory.contains);`n      if (!matchesName && !matchesCategory) continue;`n      if (normalizedName.startsWith(tokens.first)) {`n        starts.add(product);`n      }`n else if (matchesName) {`n        contains.add(product);`n      }`n else {`n        category.add(product);`n      }`n    }`n    return [...starts, ...contains, ...category];`n  }`n  void _resetAfterSale({`nrequired bool clearCustomer}`n) {`n    setState(() {`n      _descriptionController.clear();`n      _valueController.clear();`n      _quantityController.text = '1';`n      _selectedProductId = null;`n      if (clearCustomer) {`n        _customerSearchController.clear();`n        _selectedCustomer = null;`n      }`n    }`n);`n  }`n  bool get _hasDraft {`n    return _descriptionController.text.trim().isNotEmpty ||        _valueController.text.trim().isNotEmpty ||        _quantityController.text.trim() != '1' ||        _customerSearchController.text.trim().isNotEmpty ||        _productSearchController.text.trim().isNotEmpty ||        _loanDueDateController.text.trim().isNotEmpty ||        _loanInterestController.text.trim() != '2' ||        _selectedProductId != null ||        _selectedCustomer != null;`n  }`n  Future<void> _cancelSaleDraft() async {`n    if (!_hasDraft) return;`n    final shouldCancel = await showDialog<bool>(      context: context,      builder: (_) => AlertDialog(        title: const Text('Cancelar venda'),        content: const Text('Deseja limpar os dados preenchidos desta venda?'),        actions: [          TextButton(            onPressed: () => Navigator.of(context).pop(false),            child: const Text('Voltar'),          ),          FilledButton(            onPressed: () => Navigator.of(context).pop(true),            child: const Text('Cancelar venda'),          ),        ],      ),    );`n    if (shouldCancel != true || !mounted) return;`n    setState(() {`n      _mode = 'livre';`n      _paymentMethod = 'pix';`n      _productSearchController.clear();`n      _loanDueDateController.clear();`n      _loanInterestController.text = '2';`n      _loanInterestUnit = LoanInterestUnit.month;`n    }`n);`n    _resetAfterSale(clearCustomer: true);`n    ScaffoldMessenger.of(      context,    ).showSnackBar(const SnackBar(content: Text('Venda cancelada.')));`n  }`n  Future<void> _registerSale(AppStore store) async {`n    final canAccess = await _subscriptionMiddleware.checkAccess(      context,      'registerSale',    );`n    if (!canAccess) return;`n    final isFiado = _paymentMethod == 'fiado';`n    final isLoan = _paymentMethod == 'emprestimo';`n    final typedCustomer = _customerSearchController.text.trim();`n    final customerName =        _selectedCustomer?.name ??        (typedCustomer.isEmpty ? null : typedCustomer);`n    if ((isFiado || isLoan) && customerName == null) {`n      ScaffoldMessenger.of(context).showSnackBar(        SnackBar(          content: Text(            isLoan                ? 'Informe o cliente para venda de emprestimo.'                : 'Informe o cliente para venda fiado.',          ),        ),      );`n      return;`n    }`n    DateTime? loanDueDate;`n    var loanInterestRate = 2.0;`n    if (isLoan) {`n      final parts = _loanDueDateController.text.split('/');`n      if (parts.length != 3) {`n        ScaffoldMessenger.of(context).showSnackBar(          const SnackBar(content: Text('Informe o vencimento do emprestimo.')),        );`n        return;`n      }`n      loanDueDate = DateTime(        int.parse(parts[2]),        int.parse(parts[1]),        int.parse(parts[0]),      );`n      loanInterestRate =          double.tryParse(_loanInterestController.text.replaceAll(',', '.')) ??          0;`n    }`n    final mustUseProduct = _mode == 'produto';`n    if (mustUseProduct && _selectedProductId == null) {`n      ScaffoldMessenger.of(context).showSnackBar(        const SnackBar(          content: Text('Selecione um produto para venda com produto.'),        ),      );`n      return;`n    }`n    final shouldUseProduct = _selectedProductId != null;`n    late final _SaleReceiptData receiptData;`n    if (shouldUseProduct) {`n      final quantity = double.tryParse(        _quantityController.text.replaceAll(',', '.'),      );`n      if (quantity == null || quantity <= 0) {`n        ScaffoldMessenger.of(context).showSnackBar(          const SnackBar(content: Text('Informe uma quantidade valida.')),        );`n        return;`n      }`n      final error = await store.registerProductSale(        productId: _selectedProductId!,        quantity: quantity,        paymentMethod: _paymentMethod,        customerName: customerName,        loanDueDate: loanDueDate,        loanInterestRate: loanInterestRate,        loanInterestUnit: _loanInterestUnit,      );`n      if (!mounted) return;`n      if (error != null) {`n        ScaffoldMessenger.of(          context,        ).showSnackBar(SnackBar(content: Text(error)));`n        return;`n      }`n      ProductRecord? product;`n      for (final item in store.products) {`n        if (item.id == _selectedProductId) {`n          product = item;`n          break;`n        }`n      }`n      final total = (product?.salePrice ?? 0) * quantity;`n      receiptData = _SaleReceiptData(        description: 'Venda de ${`nproduct?.name ?? 'Produto'}`n',        total: total,        paymentMethod: _paymentMethod,        customerName: customerName,        productName: product?.name,        quantity: quantity,        createdAt: DateTime.now(),      );`n    }`n else {`n      final value = double.tryParse(_valueController.text.replaceAll(',', '.'));`n      if (value == null || value <= 0) {`n        ScaffoldMessenger.of(context).showSnackBar(          const SnackBar(            content: Text('Informe um valor valido para a venda livre.'),          ),        );`n        return;`n      }`n      try {`n        await store.registerFreeSale(          description: _descriptionController.text.trim().isEmpty              ? 'Venda livre'              : _descriptionController.text.trim(),          total: value,          paymentMethod: _paymentMethod,          customerName: customerName,          loanDueDate: loanDueDate,          loanInterestRate: loanInterestRate,          loanInterestUnit: _loanInterestUnit,        );`n      }`n catch (error) {`n        if (!mounted) return;`n        ScaffoldMessenger.of(          context,        ).showSnackBar(SnackBar(content: Text(_errorText(error))));`n        return;`n      }`n      if (!mounted) return;`n      receiptData = _SaleReceiptData(        description: _descriptionController.text.trim().isEmpty            ? 'Venda livre'            : _descriptionController.text.trim(),        total: value,        paymentMethod: _paymentMethod,        customerName: customerName,        productName: null,        quantity: null,        createdAt: DateTime.now(),      );`n    }`n    if (!mounted) return;`n    final action = await _askReceiptAction();`n    if (action == 'print') {`n      await _printReceipt(receiptData, store.shopProfile);`n    }`n else if (action == 'share') {`n      await _shareReceipt(receiptData, store.shopProfile);`n    }`n    _resetAfterSale(clearCustomer: isFiado);`n    if (isFiado) {`n      widget.onFiadoSaleCreated();`n    }`n    if (mounted) {`n      ScaffoldMessenger.of(context).showSnackBar(        const SnackBar(content: Text('Venda registrada com sucesso.')),      );`n    }`n  }`n  @override  Widget build(BuildContext context) {`n    final store = AppStoreScope.of(context);`n    return Scaffold(      appBar: AppBar(title: const Text('Vendas')),      body: ListenableBuilder(        listenable: store,        builder: (context, _) {`n          final allProducts = store.products.toList();`n          final products = _productMatches(allProducts);`n          final dropdownProducts = _dropdownProducts(            filtered: products,            all: allProducts,            selectedId: _selectedProductId,          );`n          final customers = store.customers.toList();`n          final sales = store.sales.toList();`n          final customerMatches = _customerMatches(customers);`n          final customerQuery = _customerSearchController.text.trim();`n          final productQuery = _productSearchController.text.trim();`n          final showProductSuggestions =              _mode == 'produto' || productQuery.isNotEmpty;`n          if (_selectedProductId != null &&              allProducts.every((p) => p.id != _selectedProductId)) {`n            _selectedProductId = null;`n          }`n          return ListView(            padding: const EdgeInsets.fromLTRB(16, 8, 16, 90),            children: [              SegmentedButton<String>(                segments: const [                  ButtonSegment<String>(                    value: 'livre',                    label: Text('Venda livre'),                  ),                  ButtonSegment<String>(                    value: 'produto',                    label: Text('Com produto'),                  ),                ],                selected: <String>{`n_mode}`n,                onSelectionChanged: (value) {`n                  setState(() {`n                    _mode = value.first;`n                  }`n);`n                }`n,              ),              const SizedBox(height: 12),              TextField(                controller: _customerSearchController,                decoration: InputDecoration(                  labelText: 'Cliente (opcional)',                  hintText: 'Digite 3 letras para buscar (ex: Ric)',                  prefixIcon: const Icon(Icons.person_search_outlined),                  suffixIcon: _customerSearchController.text.isEmpty                      ? null                      : IconButton(                          icon: const Icon(Icons.clear),                          onPressed: () {`n                            setState(() {`n                              _customerSearchController.clear();`n                              _selectedCustomer = null;`n                            }`n);`n                          }`n,                        ),                ),                onChanged: _onCustomerTextChanged,              ),              if (customerQu